      if (scopeGlobalButton) scopeGlobalButton.setAttribute('aria-pressed', scopeTarget === 'global' ? 'true' : 'false');
      if (scopePerChatButton) scopePerChatButton.setAttribute('aria-pressed', scopeTarget === 'scope' ? 'true' : 'false');
