        ok: false,
        transactionId,
        label: journal.label,
        basisHash: before.semanticHash,
        rollbackStatus: rollback.ok ? 'restored' : 'failed',
        rollbackFailures: safeClone(rollback.failures || []),
        error: compact(error?.message || error, 500),
