        if (owns('runtime')) await writeStep('runtime_settings', () => writeRuntimeSettings(payload.runtime || {}));
        if (owns('agents')) await writeStep('agent_slots', () => writeAgentSlots(payload.agents || {}));
        if (payload.removePostProcessors !== false) await writeStep('post_processors_remove', () => RisuCompat.removeItem(STORAGE_POST_PROCESSORS_KEY));
        if (owns('prompts')) await writeStep('prompt_overrides', () => writePromptOverrides(payload.prompts || {}));
