  const normalizeDraftPatchComparisonText = value => text(value || '')
    .normalize('NFKC')
    .replace(/\s+/g, ' ')
    .trim();

  const findExactDraftPatchDuplicate = (nodes = [], value = '', excludedId = '') => {
    const normalized = normalizeDraftPatchComparisonText(value);
    if (!normalized) return null;
    return nodes.find(node => (
      node?.id !== excludedId
      && normalizeDraftPatchComparisonText(node?.text) === normalized
    )) || null;
  };

  const applyDraftPatchOperations = (documentValue, editValues = []) => {
    const document = typeof documentValue === 'string'
      ? buildDraftPatchDocument(documentValue)
      : JSON.parse(JSON.stringify(documentValue || {}));
    const nodes = Array.isArray(document.blocks)
      ? document.blocks.map(block => ({ ...block, originalHash: block.originalHash || block.hash || stableDraftHash(block.text) }))
      : [];
    const applied = [];
    const skipped = [];
    const afterTail = new Map();
    const beforeTail = new Map();
    let generatedIndex = 0;
    const nextGeneratedId = () => `x${String(++generatedIndex).padStart(3, '0')}`;
    const findIndex = id => nodes.findIndex(node => node.id === id);

    for (const edit of Array.isArray(editValues) ? editValues : []) {
      const targetIndex = findIndex(edit.target);
      if (targetIndex < 0) {
        skipped.push({ ...edit, skipReason: 'target_not_found' });
        continue;
      }
      const target = nodes[targetIndex];
      if (edit.expectedHash && edit.expectedHash !== (target.originalHash || stableDraftHash(target.text))) {
        skipped.push({ ...edit, skipReason: 'target_hash_mismatch' });
        continue;
      }
      if (edit.operation === 'replace') {
        if (normalizeDraftPatchComparisonText(edit.content) === normalizeDraftPatchComparisonText(target.text)) {
          skipped.push({ ...edit, skipReason: 'replacement_unchanged', duplicateOf: target.id });
          continue;
        }
        const duplicate = findExactDraftPatchDuplicate(nodes, edit.content, target.id);
        if (duplicate) {
          skipped.push({ ...edit, skipReason: 'duplicate_existing_block', duplicateOf: duplicate.id });
          continue;
        }
        target.text = edit.content;
        target.hash = stableDraftHash(target.text);
        applied.push({ ...edit });
        continue;
      }
      if (edit.operation === 'delete') {
        if (nodes.length <= 1) {
          skipped.push({ ...edit, skipReason: 'cannot_delete_last_block' });
          continue;
        }
        const removed = nodes.splice(targetIndex, 1)[0];
        if (targetIndex > 0 && removed.separatorAfter) nodes[targetIndex - 1].separatorAfter = removed.separatorAfter;
        applied.push({ ...edit });
        continue;
      }
      if (edit.operation === 'insert_before') {
        const duplicate = findExactDraftPatchDuplicate(nodes, edit.content);
        if (duplicate) {
          skipped.push({ ...edit, skipReason: 'duplicate_existing_block', duplicateOf: duplicate.id });
          continue;
        }
        const tailId = beforeTail.get(edit.target);
        const insertionIndex = tailId ? findIndex(tailId) + 1 : targetIndex;
        const node = {
          id: nextGeneratedId(),
          text: edit.content,
          separatorAfter: '\n\n',
          hash: stableDraftHash(edit.content),
          originalHash: stableDraftHash(edit.content)
        };
        nodes.splice(Math.max(0, insertionIndex), 0, node);
        beforeTail.set(edit.target, node.id);
        applied.push({ ...edit, generatedId: node.id });
        continue;
      }
      if (edit.operation === 'insert_after') {
        const duplicate = findExactDraftPatchDuplicate(nodes, edit.content);
        if (duplicate) {
          skipped.push({ ...edit, skipReason: 'duplicate_existing_block', duplicateOf: duplicate.id });
          continue;
        }
        const tailId = afterTail.get(edit.target);
        const anchorIndex = tailId ? findIndex(tailId) : findIndex(edit.target);
        if (anchorIndex < 0) {
          skipped.push({ ...edit, skipReason: 'insert_anchor_not_found' });
          continue;
        }
        const anchor = nodes[anchorIndex];
        const inheritedSeparator = anchor.separatorAfter;
        anchor.separatorAfter = '\n\n';
        const node = {
          id: nextGeneratedId(),
          text: edit.content,
          separatorAfter: inheritedSeparator,
          hash: stableDraftHash(edit.content),
          originalHash: stableDraftHash(edit.content)
        };
        nodes.splice(anchorIndex + 1, 0, node);
        afterTail.set(edit.target, node.id);
        applied.push({ ...edit, generatedId: node.id });
      }
    }
    const draft = renderDraftPatchDocument({ ...document, blocks: nodes });
    return {
      ok: !!draft.trim(),
      draft,
      sourceHash: document.sourceHash || '',
      outputHash: stableDraftHash(draft),
      blockCountBefore: Array.isArray(document.blocks) ? document.blocks.length : 0,
      blockCountAfter: nodes.length,
      applied,
      skipped
    };
  };

