      const registry = await storage.getVerifiedJson(key.entityRegistry(scope), scope, null) || {};
      const inventory = buildKnownPersonSpanInventory({ ...active.receipt, receiptKey: active.receiptKey }, registry);
      const inventoryRevisionId = digest({ schema: inventory.schema, receiptRevisionId: active.receipt.revisionId,
        registryDigest: inventory.registryDigest, classifier: 'known_mentions_v1' });
      const inventoryKey = key.personSpanInventory(scope, worldlineId, sessionEpoch, turn,
        active.receipt.revisionId, inventoryRevisionId);
