        batchTiming.generationPhaseMs = generationFinishedAt - startedAt;
        if (state.disposed) return disposedResult();
        currentStage = pipelineResult?.currentStage || pipelineResult?.stages?.at?.(-1) || currentStage;
        let failedItoStages = asArray(work.failedStages)
          .filter(item => item?.stage && item.stage !== 'ariadne')
          .map(item => ({ stage: item.stage, label: STAGE_LABELS[item.stage] || item.stage, message: compact(item.message || '', 700), at: item.at || nowIso() }));
        let pipelineStatus = failedItoStages.length ? 'partial' : 'complete';

        abortIfRequested();
        const finalText = stripFence(stageDraft(currentStage) || work.currentDraft).trim();
        const renderValidation = validateCanonicalRenderedText(finalText);
        if (!renderValidation.ok) throw new Error(`최종 메모리 검증 실패: ${renderValidation.issues.join('|')}`);
        const ariadneStage = asArray(work.stageObjects).find(item => item?.stage === 'ariadne') || null;
        const canonicalArtifact = clone(unified ? currentStage?.finalArtifact : ariadneStage?.canonicalArtifact || null);
        // T03b: a record is labelled with the schema its artifact really has.
        // Reading it from the artifact (instead of assuming the constant) is what
