          await check();
          const readSet=await MemorySuiteStorageBridge.captureConditionalReadSet([ref.key,unifiedServerActiveKey(context.scope)]),original=await storage.getJson(ref.key,null),working=clone(memory);
          await MemorySuiteStorageBridge.assertConditionalReadSet(readSet);
