          unifiedAssert(oldOp && memoryOp && tx.operations.length===2 && unifiedServerManifestIdentity(current)===unifiedServerManifestIdentity(oldOp.before),'UNIFIED_VECTOR_METADATA_REBASE_UNSAFE');
          const plannedRef=oldOp.after.memories[String(memory.turnRange.start)],after=clone(current),nextRef=after.memories[String(memory.turnRange.start)];
          unifiedAssert(nextRef?.key===ref.key,'UNIFIED_VECTOR_REF_CHANGED');
          for(const field of ['embeddingStatus','retrievalVersion','vectorCount','updatedAt'])nextRef[field]=clone(plannedRef[field]);
          if(memoryOp.after.embedding?.status==='ready' && memoryOp.before.embedding?.status!=='ready')after.stats.embeddings=Number(current.stats.embeddings||0)+1;
          tx.rejectedMetadataOperations=[...asArray(tx.rejectedMetadataOperations),{operationId:tx.serverPrepared.body.operationId,reason:string(error.message||error)}];
