        await check();buildMemoryRetrievalProjection(memory);
        let embedding;
        try{embedding=await embedMemory(context.scope,memory,memory,{beforeVectorWrite:check});}catch(error){embedding={status:'retry_pending',reason:compact(error?.message || error,500),projectionVersion:RETRIEVAL_PROJECTION_VERSION};}
        const latest=await check(),next={...clone(memory),embedding};
        // Only derived fields change. Re-read the active identity after provider await, never save
        // the pre-await manifest or mark an old vector as a replacement text's vector.
        await storage.setJson(ref.key,next);
        unifiedAssert(digest(await storage.getJson(ref.key,null))===digest(next),'UNIFIED_VECTOR_READBACK');
        await check();
        const currentRef=latest.memories[String(memory.turnRange.start)];
        Object.assign(currentRef,{embeddingStatus:embedding.status,retrievalVersion:RETRIEVAL_PROJECTION_VERSION,vectorCount:Number(embedding.vectorCount || 0),updatedAt:nowIso()});
        if(embedding.status==='ready' && memory.embedding?.status!=='ready')latest.stats.embeddings=Number(latest.stats.embeddings || 0)+1;
        await saveManifest(context.scope,latest);
        // Keep this owner's queued scan's manifest in step, without replacing unrelated keys.
        Object.assign(ref,clone(currentRef));manifest.memories[String(memory.turnRange.start)]=clone(currentRef);manifest.stats=clone(latest.stats);
