            worldlineId: string(temporalAnchor.cursor?.worldlineId || ''),
            sessionEpoch: Number(temporalAnchor.cursor?.sessionEpoch || 0),
            turnRange: clone(asObject(temporalAnchor.cursor?.turnRange))
