    const buildReadOnlyResponseManifest = async (contextValue, pairsValue, manifestValue) => {
      const context = asObject(contextValue);
      const pairs = asArray(pairsValue);
      const authorityManifest = clone(manifestValue || defaultManifest(context.scope, pairs.length));
      const manifest = clone(authorityManifest);
      manifest.memories = asObject(manifest.memories);
      const verifiedStarts = [];
      const rejected = [];
      for (const [slot, refValue] of Object.entries(manifest.memories)) {
        const ref = asObject(refValue);
        if (ref.status !== 'committed' || ref.inheritedSessionHistory === true || Number(ref.sessionEpoch || 0) < 0) continue;
        const startTurn = Math.max(0, Number(ref?.turnRange?.start || slot || 0));
        const batch = startTurn > 0 ? batchForStart(pairs, startTurn) : [];
        const actualDigest = batch.length === BATCH_SIZE ? sourceDigest(batch) : '';
        if (startTurn > 0 && batch.length===BATCH_SIZE
          && await libraCanonicalSlotPreservationKind(context,ref,batch)) {
          verifiedStarts.push(startTurn);
          continue;
        }
        manifest.memories[slot] = {
          ...clone(ref),
          status: 'inactive',
          requestLocalInactive: true,
          requestLocalInactiveReason: actualDigest ? 'source_digest_mismatch' : 'source_batch_unavailable'
        };
        rejected.push({
          startTurn,
          key: string(ref.key || ''),
          memoryId: string(ref.memoryId || ''),
          revision: Number(ref.revision || 0),
          expectedSourceDigest: string(ref.sourceDigest || ''),
          actualSourceDigest: actualDigest
        });
      }
      manifest.branchGuard = normalizeBranchGuard({
        ...asObject(manifest.branchGuard),
        schema: BRANCH_GUARD_SCHEMA,
        status: BRANCH_GUARD_READY,
        batchSignatures: branchBatchSignaturesForPairs(pairs),
        verifiedStarts: [],
        observedTurns: pairs.length,
        completeBatches: completeBatchStarts(pairs).length
      });
      refreshCanonicalFrontiers(manifest, pairs.length);
      return {
        manifest,
        authorityManifest,
        verifiedStarts: verifiedStarts.sort((a, b) => a - b),
        rejected,
        requestLocalOnly: true,
        durableMutation: false
      };
    };







    const responseTranscriptProjection = pairsValue => {
      const pairs = asArray(pairsValue);
      return {
        pairCount: pairs.length,
        pairs: pairs.map(pair => ({
          turn: Number(pair?.turn || 0),
          userChatId: string(pair?.user?.chatId || ''),
          assistantChatId: string(pair?.assistant?.chatId || ''),
          digest: digest({ user: string(pair?.user?.text || ''), assistant: string(pair?.assistant?.text || '') })
        }))
      };
    };













    

    

    

    

    



















    // Kept only for compatibility tests/imported debug fixtures from pre-2.3.24.
    // Runtime Planner no longer asks the model to fill this structure.
    






    const continuityStateCacheIdentityForEvidence = evidencePacket => {
      const head = evidencePacket?.continuity_state?.schema === CONTINUITY_STATE_SCHEMA
        ? evidencePacket.continuity_state
        : null;
      const prompt = string(evidencePacket?.continuity_state_prompt || '');
      if (!head && !prompt) return null;
      return {
        schema: string(head?.schema || CONTINUITY_STATE_SCHEMA),
        provenanceVersion: Number(head?.provenanceVersion || 0),
        status: string(head?.status || ''),
        throughTurn: Number(head?.throughTurn || 0),
        basisFingerprint: string(head?.basis?.sourceFingerprint || ''),
        sourceDigest: string(head?.source?.sourceDigest || ''),
        semanticHash: head ? digest({
          status: head.status,
          throughTurn: head.throughTurn,
          domainStatus: head.domainStatus,
          characters: head.characters,
          relationships: head.relationships,
          world: head.world,
          basis: head.basis,
          source: head.source
        }) : '',
        promptHash: prompt ? digest(prompt) : ''
      };
    };

    const narrativeCacheIdentityForEvidence = evidencePacket => {
      const narrative = __libraCompletionUnwrapNarrative(evidencePacket?.narrative_state);
      const narrativePrompt = string(evidencePacket?.narrative_prompt || '');
      const direction = evidencePacket?.narrative_direction && typeof evidencePacket.narrative_direction === 'object' ? evidencePacket.narrative_direction : null;
      const directionPrompt = string(evidencePacket?.narrative_direction_prompt || '');
      const narrativeIdentity = narrative || narrativePrompt ? {
        schema: string(narrative?.schema || 'libra.narrative_state.v1'), revision: Number(narrative?.revision || 0),
        updatedThroughTurn: Number(narrative?.updatedThroughTurn || 0), semanticHash: narrative ? digest(narrative) : '',
        promptHash: narrativePrompt ? digest(narrativePrompt) : ''
      } : null;
      const narrativeDirectionIdentity = direction || directionPrompt ? {
        schema: string(direction?.schema || __LIBRA_NARRATIVE_DIRECTION_LEGACY_SCHEMA), scopeKey: string(direction?.scopeKey || ''),
        updatedAt: Number(direction?.updatedAt || 0), semanticHash: direction ? digest(direction) : '',
        promptHash: directionPrompt ? digest(directionPrompt) : ''
      } : null;
      return { narrativeIdentity, narrativeDirectionIdentity };
    };







    
    
    


    // Compatibility-only view helper. Protected Planner transfer keeps the full
