      const manualEdit = canonicalCandidateRequiresManualValidation(candidate, found.variant);
      if (manualEdit) {
        validateCanonicalManualAuthority(candidate,found.variant,context.scope);
        const disposition = validateManualStateDispositionIntent({ intent: candidate.manualStateDisposition, memory: candidate, variant: found.variant });
        if (string(job?.manualStateDisposition?.intentDigest || '') !== string(disposition.intentDigest || '')) throw new Error('canonical_manual_state_disposition_required');
        await validateManualStateDispositionAgainstAnchor({ context, manifest, memory: candidate, intent: disposition, job, variant: found.variant });
      }
      await validateCanonicalAdoptionBinding({scope:context.scope,found,candidate});
      const startTurn = Number(candidate.turnRange.start || 0);
      const currentRef = memoryRefForStart(manifest, startTurn);
      const comparison = asObject(job.comparison);
      const currentBatch = batchForStart(pairs, startTurn);
      const alreadySwitched = currentRef?.key === found.variant.key && Number(currentRef?.revision || 0) === Number(candidate.revision || 0);
      if (!alreadySwitched && (!currentRef || currentRef.key !== comparison?.active?.key || Number(currentRef.revision || 0) !== Number(comparison?.active?.revision || 0) || sourceDigest(currentBatch) !== candidate.sourceDigest)) throw new Error('canonical_candidate_adoption_precondition_changed');
