        unifiedAssert((await MemorySuiteStorageBridge.getMode())==='plugin_only','UNIFIED_SERVER_CANDIDATE_NOT_SUPPORTED');
        const verifiedManifest=await assertUnifiedBasis(context,candidate.unifiedBasis,'candidate_adoption');
