      if (!found.variant || found.variant.status === 'active') throw new Error(found.variant ? 'canonical_variant_already_active' : 'canonical_variant_not_found');
      if (await findPendingCanonicalChoice(context.scope, { startTurn: Number(found.slot.startTurn), variantId })) throw new Error('canonical_candidate_already_pending');
      const candidate = await storage.getJson(found.variant.key, null); if (!candidate) throw new Error('canonical_variant_record_missing');
      const activeRef = memoryRefForStart(manifest, Number(candidate.turnRange.start)); const activeMemory = await loadMemoryRef(activeRef);
