        await storage.setJson(key.canonicalVariantIndex(context.scope), indexBefore);
        const manifestReadback = await storage.getJson(key.manifest(context.scope), null);
        const indexReadback = await storage.getJson(key.canonicalVariantIndex(context.scope), null);
