      if (!run) {
        const hadManifestReference = asArray(manifest.runIds).some(idValue => string(idValue || '') === targetRunId)
          || string(manifest?.inFlight?.runId || '') === targetRunId
          || Object.values(normalizeFailedCanonicalBatches(manifest.failedBatches)).some(row => string(row?.runId || '') === targetRunId);
        if (hadManifestReference) {
          manifest.runIds = asArray(manifest.runIds).filter(idValue => string(idValue || '') !== targetRunId);
          if (string(manifest?.inFlight?.runId || '') === targetRunId) manifest.inFlight = null;
          for (const [failedStartKey, row] of Object.entries(normalizeFailedCanonicalBatches(manifest.failedBatches))) {
            if (string(row?.runId || '') === targetRunId) delete manifest.failedBatches[failedStartKey];
          }
          await saveManifest(context.scope, manifest);
        }
        return { ok: true, deleted: true, alreadyMissing: true, runId: targetRunId };
      }
      if (string(run.scopeKey || '') !== string(context.scope.scopeKey || '')) throw new Error('canonical_failed_run_scope_mismatch');
      if (string(run.status || '') !== 'failed') throw new Error('canonical_failed_run_delete_terminal_failure_only');
      if (Object.values(asObject(manifest.memories)).some(ref => string(ref?.runId || '') === targetRunId)) {
        throw new Error('canonical_failed_run_referenced_by_active_memory');
      }
      const startTurn = Number(run?.turnRange?.start || 0);
      const endTurn = Number(run?.turnRange?.end || (startTurn ? startTurn + BATCH_SIZE - 1 : 0));
      if (!startTurn) throw new Error('canonical_failed_run_turn_range_missing');
      const runKey = key.run(context.scope, targetRunId);
      const workKey = key.work(context.scope, startTurn);
      const work = await storage.getJson(workKey, null);
      const removeWork = string(work?.runId || '') === targetRunId;
      const originalManifest = clone(manifest);
      const originalHead = await storage.getJson(key.canonicalJobHead(context.scope), null);
      const jobPrefix = `${PREFIX}:scope:${context.scope.scopeKey}:canonical-job:`;
      const jobKeys = (await storage.keys()).filter(storageKey => storageKey.startsWith(jobPrefix) && !storageKey.includes('::chunk:'));
      const originalJobs = new Map();
      const updatedJobs = new Map();
      for (const jobKey of jobKeys) {
        const job = await storage.getJson(jobKey, null);
        if (job?.schema !== CANONICAL_JOB_SCHEMA || !canonicalJobTerminal(job)) continue;
        const failures = asArray(job.failures);
        const retainedFailures = failures.filter(item => Number(item?.startTurn || 0) !== startTurn || Number(item?.endTurn || endTurn) !== endTurn);
        const resultFailures = asArray(job?.result?.failures);
        const retainedResultFailures = resultFailures.filter(item => Number(item?.startTurn || 0) !== startTurn || Number(item?.endTurn || endTurn) !== endTurn);
        if (retainedFailures.length === failures.length && retainedResultFailures.length === resultFailures.length) continue;
        originalJobs.set(jobKey, clone(job));
        const removedCount = Math.max(failures.length - retainedFailures.length, resultFailures.length - retainedResultFailures.length, 1);
        const nextFailed = Math.max(0, Number(job.failed || job?.result?.failed || 0) - removedCount);
        const nextJob = {
          ...clone(job),
          failures: retainedFailures,
          failed: nextFailed,
          result: job.result && typeof job.result === 'object'
            ? { ...clone(job.result), failures: retainedResultFailures, failed: Math.max(0, Number(job.result.failed || 0) - removedCount) }
            : job.result,
          updatedAt: nowIso()
        };
        if (nextJob.state === 'completed_with_warnings' && nextFailed === 0) {
          nextJob.state = 'completed';
          nextJob.phase = 'complete';
          nextJob.message = '사용자가 실패 실행 기록을 삭제했습니다.';
        }
        updatedJobs.set(jobKey, nextJob);
      }
      try {
        manifest.runIds = asArray(manifest.runIds).filter(idValue => string(idValue || '') !== targetRunId);
        if (string(manifest?.inFlight?.runId || '') === targetRunId && string(manifest?.inFlight?.status || '') === 'failed') manifest.inFlight = null;
        for (const [failedStartKey, row] of Object.entries(normalizeFailedCanonicalBatches(manifest.failedBatches))) {
          if (string(row?.runId || '') === targetRunId) delete manifest.failedBatches[failedStartKey];
        }
        await saveManifest(context.scope, manifest);
        for (const [jobKey, job] of updatedJobs) await storage.setJson(jobKey, job);
        if (originalHead?.jobId) {
          const currentJobKey = key.canonicalJob(context.scope, originalHead.jobId);
          const updatedHeadJob = updatedJobs.get(currentJobKey);
          if (updatedHeadJob) await storage.setJson(key.canonicalJobHead(context.scope), {
            ...clone(originalHead), state: updatedHeadJob.state, updatedAt: updatedHeadJob.updatedAt
          });
        }
        if (removeWork) await storage.remove(workKey);
        await storage.remove(runKey);
        const [runReadback, workReadback, manifestReadback] = await Promise.all([
          storage.getJson(runKey, null),
          removeWork ? storage.getJson(workKey, null) : Promise.resolve(null),
          loadManifest(context.scope, pairs.length)
        ]);
        if (runReadback || workReadback
          || asArray(manifestReadback.runIds).some(idValue => string(idValue || '') === targetRunId)
          || string(manifestReadback?.inFlight?.runId || '') === targetRunId
          || Object.values(normalizeFailedCanonicalBatches(manifestReadback.failedBatches)).some(row => string(row?.runId || '') === targetRunId)) throw new Error('canonical_failed_run_delete_readback_failed');
        for (const [jobKey, job] of updatedJobs) {
          const jobReadback = await storage.getJson(jobKey, null);
          if (!jobReadback || asArray(jobReadback.failures).some(item => Number(item?.startTurn || 0) === startTurn && Number(item?.endTurn || endTurn) === endTurn)) {
            throw new Error('canonical_failed_run_job_cleanup_readback_failed');
          }
        }
        const currentJobKey = state.canonicalJob?.jobId ? key.canonicalJob(context.scope, state.canonicalJob.jobId) : '';
        if (currentJobKey && updatedJobs.has(currentJobKey)) {
          state.canonicalJob = clone(updatedJobs.get(currentJobKey));
          notifyCanonicalJob();
        }
        await refreshSnapshot(context, { suppressGuiSchedule: true, limits: state.guiSnapshotLimits || LIBRA_SNAPSHOT_PAGE_LIMITS });
        return { ok: true, deleted: true, runId: targetRunId, startTurn, endTurn, recoveryEntryRemoved: true };
      } catch (error) {
        const rollbackErrors = [];
        try { await storage.setJson(runKey, run); } catch (rollbackError) { rollbackErrors.push(rollbackError); }
        if (removeWork) { try { await storage.setJson(workKey, work); } catch (rollbackError) { rollbackErrors.push(rollbackError); } }
        try { await saveManifest(context.scope, originalManifest); } catch (rollbackError) { rollbackErrors.push(rollbackError); }
        for (const [jobKey, job] of originalJobs) { try { await storage.setJson(jobKey, job); } catch (rollbackError) { rollbackErrors.push(rollbackError); } }
        if (originalHead) { try { await storage.setJson(key.canonicalJobHead(context.scope), originalHead); } catch (rollbackError) { rollbackErrors.push(rollbackError); } }
        if (rollbackErrors.length) {
          const wrapped = new Error(`${error?.message || error}; rollback_failures=${rollbackErrors.length}`);
          wrapped.code = 'CANONICAL_FAILED_RUN_DELETE_ROLLBACK_INCOMPLETE';
          wrapped.rollbackErrors = rollbackErrors;
          throw wrapped;
        }
        throw error;
      }
