  const refreshPromptStudioOocBuilder = (expectedState, refreshProfiles = false) => {
    const node = Gui.root?.querySelector('#prompt-studio-ooc-builder');
    if (!node?.isConnected || !promptStudioOocStateIsCurrent(expectedState)) return false;
    const panel = refreshProfiles ? node.closest('[data-memory-prompt-studio]') : null;
    if (panel) {
      const disclosures = new Map(Array.from(panel.querySelectorAll('details')).map(item => [
        item.id || item.querySelector('summary')?.textContent || '', item.open
      ]));
      const next = buildLibraPromptStudioPanel();
      for (const item of next.querySelectorAll('details')) {
        const key = item.id || item.querySelector('summary')?.textContent || '';
        if (disclosures.has(key)) item.open = disclosures.get(key);
      }
      panel.replaceWith(next);
    } else node.replaceWith(renderPromptStudioOocBuilder());
    return true;
  };
